import math

def v2(u):
    return (4*u + math.sqrt(3)*(u**2 + 1)) / (3 - u**2)

# We want to find the maximum n such that there exist a_1 < a_2 < ... < a_n < sqrt(3)
# with a_{i+1} >= v2(a_i).
# To maximize n, we should pick a_i as small as possible.
# Let's try different starting values for a_1.

def find_max_n(a1):
    a = [a1]
    while True:
        u = a[-1]
        if u >= math.sqrt(3):
            break
        next_a = v2(u)
        if next_a >= math.sqrt(3):
            break
        a.append(next_a)
    return len(a)

